 public static class CareerVarietyVerification {
 static void AuthorHabits(CareerEventDefinition e){var r=e.rival;r.driverId=e.rivalName;r.limiterHoldSeconds=e.stableId=="first-pass"?0:r.seed%3==0?.2f+(r.seed%5)*.07f:0;r.riskWhenBehind=e.stableId!="first-pass"&&(r.style==RivalStyle.Aggressive||r.seed%5==0);r.riskBehindMeters=18+r.seed%24;r.riskLimiterHoldSeconds=.35f+(r.seed%5)*.1f;r.flatShiftWhenRisking=r.style==RivalStyle.Aggressive;r.confidenceFromBuild=e.stableId!="first-pass"&&r.seed%3==1&&e.opponent.spec.torque.Max(t=>t.torqueNm*t.rpm/7127)>160;if(r.confidenceFromBuild)r.style=RivalStyle.Confident;r.openingThrottle=.75f+(r.seed%5)*.025f;r.openingUntilMeters=100+r.seed%4*15;r.reactionJitterSeconds=r.style==RivalStyle.Novice?.18f:.1f;r.shiftJitterRpm=r.style==RivalStyle.Novice?220:100;r.shiftDelayMin=.02f;r.shiftDelayMax=r.style==RivalStyle.Novice?.22f:.12f;r.throttleWander=r.style==RivalStyle.Novice?.04f:.018f;r.confidenceReactionDelay=.35f;r.authoringVersion=5;EditorUtility.SetDirty(e);}
 public static void Prepare(){
 var cat=MechanicsTransactions.Catalog();
 foreach(var e in Resources.LoadAll<CareerEventDefinition>("Data/Events")){
 if(e.rival!=null&&e.rival.authored){if(e.rival.authoringVersion==0){if(e.stableId=="first-pass"){e.rival.health=.96f;e.rival.reactionSeconds=.35f;}e.rival.authoringVersion=1;EditorUtility.SetDirty(e);}if(e.rival.authoringVersion<5)AuthorHabits(e);continue;}
 uint seed=2166136261;foreach(char c in e.stableId)seed=(seed^c)*16777619;
 var style=(RivalStyle)(seed%4);
 e.rival=new RivalSetup{authoringVersion=1,authored=true,seed=(int)(seed&0x7fffffff)|1,style=style,health=.965f+(seed%5)*.003f,mileageKm=18000+seed%55000,reactionSeconds=style==RivalStyle.Aggressive?.16f:style==RivalStyle.Novice?.34f:style==RivalStyle.Conservative?.3f:.22f,throttle=style==RivalStyle.Conservative?.96f:1,shiftFraction=style==RivalStyle.Novice?.94f:style==RivalStyle.Conservative?.93f:1,hesitationInterval=style==RivalStyle.Novice?6:0,hesitationSeconds=style==RivalStyle.Novice?.09f:0};
 if(e.stableId=="first-pass"){e.rival.style=RivalStyle.Smooth;e.rival.health=.96f;e.rival.reactionSeconds=.35f;e.rival.throttle=1;e.rival.shiftFraction=.98f;e.rival.hesitationInterval=e.rival.hesitationSeconds=0;}
 if(e.opponentTune.engineLevel>0)foreach(var category in new[]{PartCategory.Pistons,PartCategory.Rods,PartCategory.Crankshaft,PartCategory.Clutch,PartCategory.Cooling,PartCategory.FuelSystem,PartCategory.Ignition}){
 var id=cat.Id(e.opponent.spec.id,category,1);if(cat.Find(id)!=null&&cat.Fits(e.opponent.spec,cat.Find(id)))e.rival.parts.Add(new RivalPart{category=category,definitionId=id,health=e.rival.health});
 }
 AuthorHabits(e);
 }
 AssetDatabase.SaveAssets();
 }
 static RaceSimulation StarterRace(PlayerProfile p,CareerEventDefinition e,bool poor=false,double difficulty=1,bool threaded=false,bool timingErrors=false,int? attemptSeed=null,double launchDelay=.12){
 var build=MechanicsOwnership.Resolve(p,p.SelectedCar,p.catalog);var rival=CareerOpponents.Capture(e,p.catalog,difficulty,attemptSeed);
 var settings=new DriverSettings{shifting=ShiftMode.Sequential,launch=LaunchMode.Assisted,throttleAssist=false,wearMode=WearMode.Full};
 var player=new CarSimulation(build.spec,build.tune,settings,p.parts);player.SetFluids(p.SelectedCar.fluids);player.SetMassInputs(build.tune.driverMassKg,0,0,0,p.SelectedCar.fuel.litres);
 var race=new RaceSimulation(player,rival.Create(),e.distanceM,rival.behavior);if(threaded)race.EnableOpponentWorker();int ticks=0;
 while(race.phase!=RacePhase.Finished&&ticks++<15000){var s=player.state;double target=poor?build.spec.redlineRpm*.53:timingErrors?build.spec.redlineRpm*.78:player.ShiftPoint(s.gear);var input=new DriverInput{throttle=poor||s.launched||race.time>=RaceSimulation.GreenAt+launchDelay?1:0,launch=race.time>=RaceSimulation.GreenAt+(poor?.85:timingErrors?.55:launchDelay)&&!s.launched,shiftUp=s.launched&&s.gear<build.spec.gears.Length&&s.shiftRemaining<=0&&s.rpm>=target};if(!poor&&s.launched&&(s.shiftRemaining>0||input.shiftUp))input.throttle=0;race.Step(input);}
 race.CloseOpponentWorker();return race;
 }
 static RaceSimulation RiskRace(MechanicalCatalog cat,CareerEventDefinition first,bool threaded){var setup=CareerOpponents.Capture(first,cat);setup.behavior.riskWhenBehind=true;setup.behavior.riskBehindMeters=3;setup.behavior.riskLimiterHoldSeconds=.6;setup.behavior.flatShiftWhenRisking=true;var spec=cat.Spec("super-v8");var build=cat.Resolve(spec.id,cat.Recipe(spec.id));var race=RaceSessionFactory.CreateCaptured(build.spec,build.tune,new DriverSettings{wearMode=WearMode.Full},setup,first.distanceM);if(threaded)race.EnableOpponentWorker();for(int tick=0;tick<20000&&race.phase!=RacePhase.Finished;tick++)race.Step(new DriverInput());race.CloseOpponentWorker();return race;}
 static RaceSimulation ConfidentRace(MechanicalCatalog cat,CareerEventDefinition first,bool reckless,out bool earlyPlayerLead){var e=UnityEngine.Object.Instantiate(first);e.opponent=Resources.LoadAll<VehicleDefinition>("Data/Vehicles").Single(v=>v.spec.id=="super-v8");e.opponentTune=e.opponent.CreateStockTune();e.rival=JsonUtility.FromJson<RivalSetup>(JsonUtility.ToJson(first.rival));e.rival.style=RivalStyle.Confident;e.rival.confidenceFromBuild=true;e.rival.openingThrottle=reckless?.15f:.8f;e.rival.openingUntilMeters=reckless?350:110;e.rival.openingEmergencyGap=reckless?1000:35;e.rival.confidenceReactionDelay=reckless?3:.35f;var capture=CareerOpponents.Capture(e,cat,1,42);UnityEngine.Object.DestroyImmediate(e);var build=cat.Resolve("starter-hatch",cat.Recipe("starter-hatch"));var race=RaceSessionFactory.CreateCaptured(build.spec,build.tune,new DriverSettings{wearMode=WearMode.Full},capture,first.distanceM);earlyPlayerLead=false;for(int tick=0;tick<20000&&race.phase!=RacePhase.Finished;tick++){race.Step(new DriverInput());if(race.opponent.state.distance<50&&race.player.state.distance>race.opponent.state.distance+1)earlyPlayerLead=true;}return race;}
 public static void RunStandalone(){
 Prepare();int checks=0;var log=new StringBuilder();Action<bool,string> check=(ok,label)=>{if(!ok)throw new InvalidOperationException(label);checks++;log.AppendLine("PASS "+label);};var cat=MechanicsTransactions.Catalog();var events=Resources.LoadAll<CareerEventDefinition>("Data/Events");var first=events.Single(e=>e.stableId=="first-pass");var folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../../reports/variety"));Directory.CreateDirectory(folder);var matrix=new StringBuilder("starter,behavior,player_total,rival_total,won,failed\n");
 foreach(var e in events){var snapshot=CareerOpponents.Capture(e,cat);var repeat=CareerOpponents.Capture(e,cat);check(JsonUtility.ToJson(snapshot.Entry())==JsonUtility.ToJson(repeat.Entry()),e.stableId+" repeatable driver and per-part hardware/wear");var npc=snapshot.Create();npc.Launch(0);for(int i=0;i<10000&&npc.state.distance<e.distanceM&&!npc.state.engineFailed&&!npc.state.drivetrainFailed;i++)npc.Step(DragMath.FixedStep,snapshot.behavior.DriveInput(npc,i*DragMath.FixedStep,0,DragMath.FixedStep));check(npc.state.distance>=e.distanceM,e.stableId+" complete matched rival survives its normal habit-driven pass");}
 var captured=CareerOpponents.Capture(first,cat);var recorded=captured.Entry();
 var rivalTires=captured.components.Single(p=>p.slot==PartCategory.Tires.ToString());
 check(rivalTires.condition.elements.Length==4&&rivalTires.condition.tires.All(t=>t.Validate()==null)
     &&rivalTires.condition.tires.Select((t,i)=>t.id==rivalTires.instanceId+"/tire/"+i
         &&t.definitionId==rivalTires.definitionId&&t.health<1&&t.consumedLife>0
         &&t.distanceM==first.rival.mileageKm*1000).All(ok=>ok)
     &&rivalTires.condition.health==1&&rivalTires.condition.distanceM==0,
     "First career rival stages with four identified, worn tires and neutral container state");
 string frozen=JsonUtility.ToJson(recorded);captured.components[0].condition.health=.2f;captured.tune.shiftRpm=1000;check(frozen==JsonUtility.ToJson(recorded),"Entry freezes actual hardware condition and tune independently of the live rival");
 foreach(string invalid in new[]{"health","duplicate","behavior"}){var candidate=UnityEngine.Object.Instantiate(first);candidate.rival=JsonUtility.FromJson<RivalSetup>(JsonUtility.ToJson(first.rival));if(invalid=="health")candidate.rival.parts.Add(new RivalPart{category=PartCategory.Pistons,health=float.NaN});else if(invalid=="duplicate"){candidate.rival.parts.Add(new RivalPart{category=PartCategory.Pistons});candidate.rival.parts.Add(new RivalPart{category=PartCategory.Pistons});}else candidate.rival.throttle=float.NaN;bool rejected=false;try{CareerOpponents.Capture(candidate,cat);}catch(InvalidOperationException){rejected=true;}UnityEngine.Object.DestroyImmediate(candidate);check(rejected,"Invalid authored rival "+invalid+" rejected before creating a race");}
 var badEntry=CareerOpponents.Capture(first,cat).Entry();badEntry.behavior.throttle=double.NaN;check(CareerOpponents.ValidateEntry(badEntry)!=null,"Corrupt saved rival behavior rejected");
 check(events.Any(e=>e.rival.limiterHoldSeconds>0)&&events.Any(e=>e.rival.riskWhenBehind)&&events.Select(e=>e.rival.driverId).Distinct().Count()>3,"Drivers author distinct limiter habits and willingness to risk damage");
 var habit=CareerOpponents.Capture(first,cat);habit.behavior.limiterHoldSeconds=.3;habit.behavior.shiftDelayMin=habit.behavior.shiftDelayMax=0;habit.behavior.riskWhenBehind=true;habit.behavior.riskBehindMeters=25;habit.behavior.flatShiftWhenRisking=true;var habitCar=habit.Create();habitCar.Launch(0);habitCar.state.speed=20;habitCar.state.clutch=0;habitCar.state.clutchSlipRpm=0;habitCar.state.rpm=habitCar.engine.limitRpm;var pedal=habit.behavior.DriveInput(habitCar,1,0,.1);check(!pedal.shiftUp&&habitCar.driver.shifting==ShiftMode.Sequential,"Limiter habit waits physically at the cut rather than auto shifting");habit.behavior.DriveInput(habitCar,1.1,0,.1);pedal=habit.behavior.DriveInput(habitCar,1.2,0,.1);check(pedal.shiftUp,"Habit upshifts after its bounded limiter dwell");habitCar.state.shiftRemaining=.2;pedal=habit.behavior.DriveInput(habitCar,1.3,30,.01);check(habit.behavior.RiskActive&&pedal.throttle==1,"Behind driver may flat shift with full throttle and ordinary physical risks");pedal=habit.behavior.DriveInput(habitCar,1.4,10,.01);check(!habit.behavior.RiskActive&&pedal.throttle==0,"Recovered gap restores normal manual lift with hysteresis");
 var risking=RiskRace(cat,first,false);var riskingParallel=RiskRace(cat,first,true);check(risking.opponentBehavior.RiskEngagements>0&&risking.opponentBehavior.HeldLimiterSeconds>0,"Real race lead activates risk and actual limiter dwelling");check(risking.playerWon,"Risk response never guarantees the trailing rival a victory");check(JsonUtility.ToJson(risking.opponent.state)==JsonUtility.ToJson(riskingParallel.opponent.state)&&risking.opponentBehavior.RiskEngagements==riskingParallel.opponentBehavior.RiskEngagements,"Adaptive driver uses the same pre-tick gap in worker and synchronous simulation");
 var confident=ConfidentRace(cat,first,false,out bool earlyLead);check(confident.opponentBehavior.confidenceActivated&&earlyLead&&confident.opponentBehavior.OpeningPhaseEnded&&!confident.playerWon,"Cocky stronger build gives an early lead then physically catches up and wins / confidence="+confident.opponentBehavior.confidenceActivated+" / hp ratio="+confident.opponentBehavior.powerAdvantage+" / torque ratio="+confident.opponentBehavior.torqueAdvantage+" / weight ratio="+confident.opponentBehavior.powerToWeightAdvantage+" / early lead="+earlyLead+" / pushed="+confident.opponentBehavior.OpeningPhaseEnded+" / player won="+confident.playerWon+" / npc failed="+confident.opponent.state.engineFailed+" / npc ET="+confident.opponent.state.elapsed+" / npc distance="+confident.opponent.state.distance+" / npc finished="+confident.opponent.state.finished+" / drive failed="+confident.opponent.state.drivetrainFailed+" / player ET="+confident.player.state.elapsed+" / npc reaction="+confident.opponent.state.reaction+" / player reaction="+confident.player.state.reaction);var reckless=ConfidentRace(cat,first,true,out bool recklessLead);check(reckless.opponentBehavior.confidenceActivated&&recklessLead&&reckless.playerWon,"Excessively cocky strategy can lose despite greater output");var equalCapture=CareerOpponents.Capture(first,cat);equalCapture.behavior.confidenceFromBuild=true;var same=equalCapture.Create();var equalRace=new RaceSimulation(equalCapture.Create(),same,first.distanceM,equalCapture.behavior);check(!equalRace.opponentBehavior.confidenceActivated,"Equal-output matchup does not activate build-based confidence");
 var refreshCapture=CareerOpponents.Capture(first,cat);refreshCapture.behavior.confidenceFromBuild=true;var powerful=cat.Resolve("super-v8",cat.Recipe("super-v8"));var refreshRace=new RaceSimulation(refreshCapture.Create(),new CarSimulation(powerful.spec,powerful.tune,new DriverSettings()),first.distanceM,refreshCapture.behavior);refreshRace.RefreshOpponentStrategy();double plannedReaction=refreshRace.opponent.driver.reactionSeconds;refreshRace.RefreshOpponentStrategy();check(Math.Abs(plannedReaction-refreshRace.opponent.driver.reactionSeconds)<1e-12,"Hydrated fuel/fluids strategy refresh does not accumulate reaction delays");
 var seedA=CareerOpponents.Capture(first,cat,1,1);var seedB=CareerOpponents.Capture(first,cat,1,2);check(seedA.components.Select(JsonUtility.ToJson).SequenceEqual(seedB.components.Select(JsonUtility.ToJson))&&seedA.driver.reactionSeconds!=seedB.driver.reactionSeconds,"Attempts vary driver response while authored hardware/wear stay identical");
 foreach(var initial in new[]{"starter-hatch","juniper-economy","juniper-club"}){
 var p=PlayerProfile.NewGame(DateTime.UtcNow.Ticks);VehicleListings.Initialize(p,cat,12345);MechanicsOwnership.Ensure(p,cat);VehicleCollection.Buy(p,cat,p.vehicleStock.listings.Single(o=>o.model==initial));
 foreach(bool poor in new[]{false,true}){var race=StarterRace(p,first,poor);double total=race.player.state.reaction+race.player.state.elapsed,opponent=race.opponent.state.reaction+race.opponent.state.elapsed;matrix.AppendLine(string.Join(",",initial,poor?"poor":"good",total.ToString("F3",System.Globalization.CultureInfo.InvariantCulture),opponent.ToString("F3",System.Globalization.CultureInfo.InvariantCulture),race.playerWon,race.player.state.engineFailed||race.player.state.drivetrainFailed));check(poor?!race.playerWon:race.playerWon,initial+(poor?" poor launch/early shifts lose":" controlled launch/proper lifted shifts win"));check(!race.player.state.engineFailed&&!race.player.state.drivetrainFailed,initial+" ordinary first-pass hardware survives");if(!poor){check(opponent-total>=.2&&opponent-total<1.2,initial+" normal first-race margin remains close");var parallel=StarterRace(p,first,false,1,true);check(JsonUtility.ToJson(race.opponent.state)==JsonUtility.ToJson(parallel.opponent.state)&&race.playerWon==parallel.playerWon,initial+" authored driver/physics worker parity");}}
 var mistimed=StarterRace(p,first,false,1,false,true);matrix.AppendLine(initial+",timing-errors,"+(mistimed.player.state.reaction+mistimed.player.state.elapsed).ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+","+(mistimed.opponent.state.reaction+mistimed.opponent.state.elapsed).ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+","+mistimed.playerWon+",False");check(!mistimed.playerWon,initial+" moderately early shifts and delayed launch lose");
 var npc=CareerOpponents.Capture(first,cat);var losing=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(p));MechanicsOwnership.Ensure(losing,cat);int initialCash=losing.cash;CareerProgression.Enter(losing,"first-loss-"+initial,losing.SelectedCar.instanceId,first,false,npc.Entry());CareerProgression.Settle(losing,"first-loss-"+initial,mistimed);check(losing.careerWins.Count==0&&losing.reputation==0&&losing.cash==initialCash+first.cashLoss&&losing.careerRuns.Last().outcome=="Loss",initial+" first actual career attempt can lose without qualification or first-win bonus");
 string original=JsonUtility.ToJson(p);CareerProgression.Enter(p,"test-first-"+initial,p.SelectedCar.instanceId,first,false,npc.Entry());var win=StarterRace(p,first);CareerProgression.Settle(p,"test-first-"+initial,win);check(p.careerWins.Contains("first-pass")&&p.reputation==first.reputationWin&&p.cash>0&&p.careerRuns.Last().rival.hardware.Any(h=>h.health<1),initial+" purchased starter earns first career progress with captured rival wear");check(p.vehicleStock.completedRuns==1,"Career settlement refresh counter advances once");bool duplicate=false;try{CareerProgression.Settle(p,"test-first-"+initial,win);}catch(InvalidOperationException){duplicate=true;}check(duplicate&&p.vehicleStock.completedRuns==1,"Repeated settlement cannot pay or refresh again");check(MechanicsOwnership.Validate(p,cat)==null,"Captured rival and purchased ownership ledger remain valid");
 var copied=JsonUtility.FromJson<PlayerProfile>(JsonUtility.ToJson(p));MechanicsOwnership.Ensure(copied,cat);check(SnapshotEquality.Profile(JsonUtility.ToJson(p),copied,cat),"Purchased/career/rival snapshot reload retains state");
 if(initial=="starter-hatch"){int wins=0,losses=0;var variation=new StringBuilder("seed,player_total,rival_total,won\n");for(int seed=1;seed<=16;seed++){var attempt=StarterRace(p,first,false,1,false,false,seed,.5);if(attempt.playerWon)wins++;else losses++;variation.AppendLine(seed+","+(attempt.player.state.elapsed+attempt.player.state.reaction).ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+","+(attempt.opponent.state.elapsed+attempt.opponent.state.reaction).ToString("F3",System.Globalization.CultureInfo.InvariantCulture)+","+attempt.playerWon);}check(wins>0&&losses>0,"Identical borderline player inputs can win or lose against different driver attempt seeds");var replay=StarterRace(p,first,false,1,false,false,8,.5);var threadedReplay=StarterRace(p,first,false,1,true,false,8,.5);check(JsonUtility.ToJson(replay.opponent.state)==JsonUtility.ToJson(threadedReplay.opponent.state)&&replay.playerWon==threadedReplay.playerWon,"Recorded driving seed reproduces human variation exactly in both execution modes");log.AppendLine(variation.ToString());}

 }
 File.WriteAllText(Path.Combine(folder,"starter-balance.csv"),matrix.ToString(),new UTF8Encoding(false));log.AppendLine(matrix.ToString());File.WriteAllText(Path.Combine(folder,"career-verification.txt"),log+"TOTAL "+checks,new UTF8Encoding(false));Debug.Log("Career variety checks: "+checks);
